//! Golden vectors generated by the real TypeScript code (`tools/golden`).

use std::collections::BTreeMap;

use serde::Deserialize;

const FNV: &str = include_str!(concat!(
    env!("CARGO_MANIFEST_DIR"),
    "/../../tests/golden-vectors/fnv-shares.json"
));

#[derive(Deserialize)]
struct File {
    cases: Vec<Case>,
}

#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct Case {
    id: String,
    value: String,
    utf16_code_units: usize,
    fnv1a32: u32,
    fnv1a32_hex: String,
    wallet_shard16: u32,
    shards: BTreeMap<String, u32>,
}

#[test]
fn fnv_and_shard_vectors_match_typescript() {
    let file: File = serde_json::from_str(FNV).expect("fnv vectors");
    assert_eq!(file.cases.len(), 20);
    for case in file.cases {
        assert_eq!(
            case.value.encode_utf16().count(),
            case.utf16_code_units,
            "{}",
            case.id
        );
        let hash = pg_crypto::fnv::fnv1a32_utf16(&case.value);
        assert_eq!(hash, case.fnv1a32, "{}", case.id);
        assert_eq!(format!("{hash:08x}"), case.fnv1a32_hex, "{}", case.id);
        for (count, expected) in &case.shards {
            let count: u32 = count.parse().expect("shard width");
            assert_eq!(
                pg_crypto::fnv::shard_index(&case.value, count),
                *expected,
                "{} width {}",
                case.id,
                count
            );
        }
        // The MERCHANT_WALLET pin lives in ledger routing; the vector records its shard as 0.
        assert_eq!(case.wallet_shard16, 0);
        assert_eq!(pg_crypto::fnv::shard_index(&case.value, 0), 0);
    }
}

#[test]
fn known_reference_values() {
    assert_eq!(pg_crypto::fnv::fnv1a32_utf16(""), 0x811c_9dc5);
    assert_eq!(pg_crypto::fnv::fnv1a32_utf16("a"), 0xe40c_292c);
    assert_eq!(pg_crypto::fnv::fnv1a32_utf16("foobar"), 0xbf9c_f968);
}
